        for(var i=0;i<W.length;i++){var rr=r0+d[0]*i,cc=c0+d[1]*i;if(rr<0||rr>=rows||cc<0||cc>=cols){fit=false;break;}var ch=g[rr][cc];if(ch&&ch!==W[i]){fit=false;break;}if(ch)over++;cells.push([rr,cc]);}
