var TEMPLATE='library | A place where you can borrow books\numbrella | You open it when it rains\nbreakfast | The first meal of the day\nkitchen | The room where you cook food\nbicycle | It has two wheels and pedals\nteacher | A person who works at a school';

function curKey(){return curE<0?null:P.entries[curE].cells[curI];}
