  var e=P.entries[ei];
  setActiveClue(e.clue);
  clueEls.forEach(function(b,k){b.classList.toggle('is-active',k===ei);});
  if(window.innerWidth>860){var box=$('cwclues'),b=clueEls[ei],top=b.offsetTop-box.offsetTop;if(top<box.scrollTop||top+b.offsetHeight>box.scrollTop+box.clientHeight)box.scrollTop=top-box.clientHeight/3;}
