    cueLater(function(){e.cells.forEach(function(k,i){var f=fill[k];if(f.lock||e.solved||!f.v||f.v===e.ans[i])return;f.v='';f.bad=false;renderCell(k);cellEls[k].classList.remove('is-bad');});placeInput();},950);
