  for(var sx=10;sx<=34;sx+=4){var ty=15-Math.sqrt(Math.max(0,1-Math.pow((sx-24)/15,2)))*9.4;tri([sx-2,ty+2],[sx+2,ty+2],[sx,ty-2.5],'#E0A030');}
