  for(var t=0;t<=1;t+=.05){put(23+(14-23)*t,3+(11-3)*t,'#7FC08F');put(23+(24-23)*t,3+(13-3)*t,'#7FC08F');put(23+(33-23)*t,3+(11-3)*t,'#7FC08F');}
  tube([[35,12],[41,11],[43,17]],4.2,3.6,G);
  ell(42,22.3,4.5,2.2,G);put(45,24,'#F4F0E0');put(47,24,'#F4F0E0');put(43,24,'#F4F0E0');
  ell(48,18,6.2,4.4,G);ell(54.5,19.2,4.4,3.1,G);
  for(t=0;t<=1;t+=.1){put(45+(39-45)*t,14.5+(9.5-14.5)*t,'#E0A030');put(48+(44.5-48)*t,14+(8.5-14)*t,'#F2C14E');}
  put(48,17,'#14101C');put(49,17,'#14101C');put(50,17,'#14101C');put(48,16,'#7FC08F');put(49,16,'#7FC08F');
  put(57,18,'#14101C');put(53,21,'#93B356');put(54,21,'#93B356');put(55,21,'#93B356');put(56,21,'#93B356');
  var o=m.slice();
