function parseTask(raw){
  var out=[],bad=[],many=[];
  raw.split(/\r?\n/).forEach(function(line,i){
    var l=line.trim();if(!l)return;
    var parts=l.split('|').map(function(s){return s.trim();}).filter(function(s){return s;});
    var ans=[];
    parts.slice(1).forEach(function(a){if(!ans.some(function(x){return x.toLowerCase()===a.toLowerCase();}))ans.push(a);});
    if(parts.length<1||ans.length<2){bad.push(i+1);return;}
    if(ans.length>4){many.push(i+1);return;}
    out.push({q:parts[0],a:ans});
  });
  return {items:out,bad:bad,many:many};
}
function checkInput(){
  var p=parseTask($('lvtin').value);
  if(p.bad.length)setMsg('Line '+p.bad[0]+': add a question and at least two answers — question | right | wrong',true);
  else if(p.many.length)setMsg('Line '+p.many[0]+': too many answers — use the right one and up to 3 wrong ones',true);
  else if(p.items.length)setMsg(p.items.length+(p.items.length===1?' question':' questions')+' ready',false);
  else setMsg('',false);
  return p;
}
