  var lo=small||short?16:20,hi=short?34:small?42:64,best=lo;
  while(lo<=hi){var m=(lo+hi)>>1;el.style.fontSize=m+'px';if(el.scrollHeight<=maxH+1&&el.scrollWidth<=el.clientWidth+1){best=m;lo=m+1;}else hi=m-1;}
