  G.SW=Math.round(small?G.W-20:Math.min(G.W*.62,Math.max(500,G.W*.42)));G.SBH=Math.round(small?Math.min(78,Math.max(52,G.H*.19)):Math.max(Math.min(82,G.H*.2),Math.min(112,G.H*.1)));
  G.FMAX=small?22:Math.min(46,Math.max(30,Math.round(G.BH*.3)));G.FMAXS=small?20:Math.min(36,Math.max(26,Math.round(G.SBH*.34)));
  G.STEP=G.SBH+(small?8:14)+(world==='tower'?14:0);
