  var hh=$('snughero').offsetHeight||70,nl=items.length?items[items.length-1].a.length:1,lt=items.length-1,ext=G.stacks[lt]?(nl-1)/2*G.STEP+G.SBH/2:G.BH/2;
  G.padTop=items.length?Math.max(0,Math.round(hh+16+ext-G.rowH[lt]/2)):0;
