var pxTimer=null,zapTimer=null;
function snugClear(){lvRun++;snugTimers.forEach(clearTimeout);snugTimers=[];busy=false;snugState('');$('snughero').classList.remove('is-walk');clearInterval(pxTimer);clearInterval(zapTimer);}
function setFrame(n){var s=$('snugsprite').firstElementChild;if(!s)return;s.querySelectorAll('.fr').forEach(function(g){g.classList.toggle('on',g.classList.contains('fr-'+n));});}
